query:
    query GetEpisode($episodeId: String!, $participatedUsersSize: Int!) {
  episode(episodeId: $episodeId) {
    episodeId
    title
    description
    videoUrl
    videoLengthInMs
    dayId
    episodeNo
    indexedSegments {
      offsetInSeconds
      lengthInSeconds
      handOffsets {
        handId
        startTimestamp
        episodeOffsetInSeconds
        handLengthInSeconds
      }
    }
    festival {
      uuid
      name
    }
    tournament {
      uuid
      name
      days {
        uuid
        name
      }
      episodes {
        episodeId
        dayId
      }
    }
    participatedUsers(size: $participatedUsersSize) {
      uuid
      nickname
      photo {
        uuid
        cdnPath
      }
      countryCode
    }
  }
}
